window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-88a4469791ba3669"]={"versions": [{"id": "FIG-88a4469791ba3669", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Prozessdiagramm zur Veranschaulichung der AUTOSAR-Methodik (AUTOSAR Methodology). Es stellt die aufeinanderfolgenden Kernphasen von der anfänglichen Systemkonfiguration bis hin zur Erstellung der ausführbaren ECU-Binärdatei dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Prozessschritte (gelbe Pfeilblöcke/Chevron-Symbole) und Artefakte (blaue Dateisymbole mit Dateityp-Beschriftung):</p>\n<ul class=\"fig-list\"><li>Artefakte:\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code> (.XML)\n</li><li><code>System Configuration Description : System</code> (.XML)\n</li><li><code>ECU Extract of System Configuration : System</code> (.XML)\n</li><li><code>ECU Configuration Description : ECU</code> (.XML, Beschriftung unten am Symbol)\n</li><li><code>ECU Executable</code> (.exe)\n</li></ul>\n</li><li>Aktivitäten / Prozessschritte:\n<ul class=\"fig-list\"><li><code>Configure System</code>\n</li><li><code>Extract ECU-Specific Information</code>\n</li><li><code>Configure ECU</code>\n</li><li><code>Generate Executable</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten sind als gerichtete Verbindungspfeile zwischen Artefakten und Bearbeitungsschritten modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf folgt einer streng sequenziellen Kette:</p>\n<ol class=\"fig-list\"><li><code>System Configuration Input : System</code> dient als Eingabe für die Aktivität <code>Configure System</code>.\n</li><li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.\n</li><li>Aus der <code>System Configuration Description : System</code> werden im Schritt <code>Extract ECU-Specific Information</code> die steuergerätespezifischen Anteile extrahiert.\n</li><li>Das Ergebnis ist das <code>ECU Extract of System Configuration : System</code>.\n</li><li>Auf Basis dieses Extrakts erfolgt der Schritt <code>Configure ECU</code>.\n</li><li>Dies liefert die <code>ECU Configuration Description : ECU</code> (ECU-Konfiguration).\n</li><li>Aus der ECU-Konfiguration generiert der Schritt <code>Generate Executable</code> die lauffähige Binärdatei <code>ECU Executable</code> (.exe).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild bietet eine vereinfachte, informative Gesamtübersicht der AUTOSAR-Methodik. Für Implementierer und Werkzeughersteller ist die strikte Entkopplung von Systemebene und ECU-Ebene essenziell: Der Datenaustausch zwischen OEM und Tier-1-Zulieferer erfolgt typischerweise über das standardisierte XML-Format des ECU-Extrakts, bevor die detaillierte BSW-, RTE- und SWC-ECU-Konfiguration sowie die finale Code-Generierung und Kompilierung stattfinden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-de8f3592df2dc1b1", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Prozessdiagramm zur Veranschaulichung der AUTOSAR-Methodik (AUTOSAR Methodology). Es stellt die aufeinanderfolgenden Kernphasen von der anfänglichen Systemkonfiguration bis hin zur Erstellung der ausführbaren ECU-Binärdatei dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Prozessschritte (gelbe Pfeilblöcke/Chevron-Symbole) und Artefakte (blaue Dateisymbole mit Dateityp-Beschriftung):</p>\n<ul class=\"fig-list\"><li>Artefakte:\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code> (.XML)\n</li><li><code>System Configuration Description : System</code> (.XML)\n</li><li><code>ECU Extract of System Configuration : System</code> (.XML)\n</li><li><code>ECU Configuration Description : ECU</code> (.XML, Beschriftung unten am Symbol)\n</li><li><code>ECU Executable</code> (.exe)\n</li></ul>\n</li><li>Aktivitäten / Prozessschritte:\n<ul class=\"fig-list\"><li><code>Configure System</code>\n</li><li><code>Extract ECU-Specific Information</code>\n</li><li><code>Configure ECU</code>\n</li><li><code>Generate Executable</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten sind als gerichtete Verbindungspfeile zwischen Artefakten und Bearbeitungsschritten modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf folgt einer streng sequenziellen Kette:</p>\n<ol class=\"fig-list\"><li><code>System Configuration Input : System</code> dient als Eingabe für die Aktivität <code>Configure System</code>.\n</li><li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.\n</li><li>Aus der <code>System Configuration Description : System</code> werden im Schritt <code>Extract ECU-Specific Information</code> die steuergerätespezifischen Anteile extrahiert.\n</li><li>Das Ergebnis ist das <code>ECU Extract of System Configuration : System</code>.\n</li><li>Auf Basis dieses Extrakts erfolgt der Schritt <code>Configure ECU</code>.\n</li><li>Dies liefert die <code>ECU Configuration Description : ECU</code> (ECU-Konfiguration).\n</li><li>Aus der ECU-Konfiguration generiert der Schritt <code>Generate Executable</code> die lauffähige Binärdatei <code>ECU Executable</code> (.exe).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild bietet eine vereinfachte, informative Gesamtübersicht der AUTOSAR-Methodik. Für Implementierer und Werkzeughersteller ist die strikte Entkopplung von Systemebene und ECU-Ebene essenziell: Der Datenaustausch zwischen OEM und Tier-1-Zulieferer erfolgt typischerweise über das standardisierte XML-Format des ECU-Extrakts, bevor die detaillierte BSW-, RTE- und SWC-ECU-Konfiguration sowie die finale Code-Generierung und Kompilierung stattfinden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ad6eecb880ce3732", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Prozessdiagramm zur Veranschaulichung der AUTOSAR-Methodik (AUTOSAR Methodology). Es stellt die aufeinanderfolgenden Kernphasen von der anfänglichen Systemkonfiguration bis hin zur Erstellung der ausführbaren ECU-Binärdatei dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in Prozessschritte (gelbe Pfeilblöcke/Chevron-Symbole) und Artefakte (blaue Dateisymbole mit Dateityp-Beschriftung):</p>\n<ul class=\"fig-list\"><li>Artefakte:\n<ul class=\"fig-list\"><li><code>System Configuration Input : System</code> (.XML)\n</li><li><code>System Configuration Description : System</code> (.XML)\n</li><li><code>ECU Extract of System Configuration : System</code> (.XML)\n</li><li><code>ECU Configuration Description : ECU</code> (.XML, Beschriftung unten am Symbol)\n</li><li><code>ECU Executable</code> (.exe)\n</li></ul>\n</li><li>Aktivitäten / Prozessschritte:\n<ul class=\"fig-list\"><li><code>Configure System</code>\n</li><li><code>Extract ECU-Specific Information</code>\n</li><li><code>Configure ECU</code>\n</li><li><code>Generate Executable</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten sind als gerichtete Verbindungspfeile zwischen Artefakten und Bearbeitungsschritten modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf folgt einer streng sequenziellen Kette:</p>\n<ol class=\"fig-list\"><li><code>System Configuration Input : System</code> dient als Eingabe für die Aktivität <code>Configure System</code>.\n</li><li><code>Configure System</code> erzeugt die <code>System Configuration Description : System</code>.\n</li><li>Aus der <code>System Configuration Description : System</code> werden im Schritt <code>Extract ECU-Specific Information</code> die steuergerätespezifischen Anteile extrahiert.\n</li><li>Das Ergebnis ist das <code>ECU Extract of System Configuration : System</code>.\n</li><li>Auf Basis dieses Extrakts erfolgt der Schritt <code>Configure ECU</code>.\n</li><li>Dies liefert die <code>ECU Configuration Description : ECU</code> (ECU-Konfiguration).\n</li><li>Aus der ECU-Konfiguration generiert der Schritt <code>Generate Executable</code> die lauffähige Binärdatei <code>ECU Executable</code> (.exe).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild bietet eine vereinfachte, informative Gesamtübersicht der AUTOSAR-Methodik. Für Implementierer und Werkzeughersteller ist die strikte Entkopplung von Systemebene und ECU-Ebene essenziell: Der Datenaustausch zwischen OEM und Tier-1-Zulieferer erfolgt typischerweise über das standardisierte XML-Format des ECU-Extrakts, bevor die detaillierte BSW-, RTE- und SWC-ECU-Konfiguration sowie die finale Code-Generierung und Kompilierung stattfinden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-88a4469791ba3669", "to": "FIG-de8f3592df2dc1b1", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-de8f3592df2dc1b1", "to": "FIG-ad6eecb880ce3732", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
